// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    LogHelper logh;

    function setUp() public {
        c = new C();
        logh = new LogHelper();
        // wire a real log so Put's high-level call to LogFile succeeds
        (bool s1, ) = address(c).call(abi.encodeWithSignature("SetLogFile(address)", address(logh)));
        require(s1, "SetLogFile failed");
        c.SetMinSum(0);
        c.Initialized();
    }

    function testFuzz_property(uint256 amount, address actor, uint256 lockTime) public {
        vm.assume(actor != address(0));
        vm.assume(uint160(actor) > 100); // avoid precompile range
        amount = bound(amount, 1, 100 ether);
        lockTime = bound(lockTime, 0, 1e12);

        vm.deal(actor, amount);
        vm.prank(actor);
        c.Put{value: amount}(lockTime);

        // GENERAL RULE: a deposit via Put is always recorded in the caller's account balance.
        assertTrue(c.Acc(actor) == amount, "a deposited amount must be recorded in Acc[actor].balance");
    }
}

