// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public {
        c = new C();
        c.SetLogFile(address(new Log()));
        c.Initialized();
    }
    function testFuzz_property(uint256 amount, uint256 minSum, uint256 lockTime, address actor) public {
        vm.assume(actor != address(0) && actor != address(c) && actor != address(this));
        amount = bound(amount, 1, 1e30);
        minSum = bound(minSum, 0, amount - 1);
        lockTime = bound(lockTime, 0, 1e12);

        vm.deal(actor, amount);
        vm.prank(actor);
        c.Put{value: amount}(lockTime);

        vm.warp(block.timestamp + lockTime + 1);
        vm.prank(actor);
        c.Collect(minSum);

        assertTrue(c.Acc(actor).balance == amount - minSum);
    }
}

contract Log {
    struct Message {
        address Sender;
        string Data;
        uint Val;
        uint Time;
    }
    Message[] public History;
    Message LastMsg;
    function AddMessage(address _adr, uint _val, string memory _data) public {
        LastMsg.Sender = _adr;
        LastMsg.Time = block.timestamp;
        LastMsg.Val = _val;
        LastMsg.Data = _data;
        History.push(LastMsg);
    }
}

