pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    address actor;

    function setUp() public {
        c = new C();
        actor = address(0xA11CE);
    }

    function testFuzz_property(uint256 warpTime, uint256 firstLock, uint256 secondLock) public {
        firstLock = bound(firstLock, 1, 365 days);
        secondLock = bound(secondLock, 1, 365 days);
        vm.warp(warpTime);
        vm.deal(actor, 1 ether);

        vm.prank(actor);
        c.Put{value: 1 ether}(firstLock);
        uint256 afterFirst = c.Acc(actor).unlockTime;

        vm.prank(actor);
        c.Put{value: 1 wei}(secondLock);
        uint256 afterSecond = c.Acc(actor).unlockTime;

        assertTrue(afterSecond >= afterFirst);
    }
}
